Certainly! Below is an example of a complex smart contract written in Solidity, a programming language for Ethereum smart contracts. This contract is designed for a decentralized voting system that ensures transparency, security, and fairness.

```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract DecentralizedVoting {
    struct Candidate {
        string name;
        uint voteCount;
    }

    struct Voter {
        bool authorized;
        bool voted;
        uint vote;
    }

    address public owner;
    string public electionName;
    mapping(address => Voter) public voters;
    Candidate[] public candidates;
    uint public totalCandidates;

    event Vote(address indexed voter, uint candidateIndex, bool vote);
    event CandidateAdded(string name);
    event CandidateRemoved(uint candidateIndex);

    modifier onlyOwner() {
        require(msg.sender == owner, "Only owner can perform this action");
        _;
    }

    modifier onlyAuthorized() {
        require(voters[msg.sender].authorized, "Not authorized to vote");
        _;
    }

    constructor(string memory _electionName) {
        owner = msg.sender;
        electionName = _electionName;
    }

    function addCandidate(string memory _name) public onlyOwner {
        candidates.push(Candidate({name: _name, voteCount: 0}));
        totalCandidates++;
        emit CandidateAdded(_name);
    }

    function removeCandidate(uint _index) public onlyOwner {
        require(_index < totalCandidates, "Invalid candidate index");
        for (uint i = 0; i < totalCandidates; i++) {
            if (i == _index) {
                candidates[i] = candidates[totalCandidates - 1];
            } else {
                candidates[i] = candidates[i - 1];
            }
        }
        candidates.pop();
        totalCandidates--;
        emit CandidateRemoved(_index);
    }

    function authorizeVoter(address _voter) public onlyOwner {
        voters[_voter].authorized = true;
    }

    function vote(uint _candidateIndex) public onlyAuthorized {
        require(!voters[msg.sender].voted, "Already voted");
        require(_candidateIndex < totalCandidates, "Invalid candidate index");

        voters[msg.sender].vote = _candidateIndex;
        voters[msg.sender].voted = true;

        candidates[_candidateIndex].voteCount += 1;
        emit Vote(msg.sender, _candidateIndex, true);
    }

    function getCandidateCount() public view returns (uint) {
        return totalCandidates;
    }

    function getCandidate(uint _index) public view returns (Candidate memory) {
        require(_index < totalCandidates, "Invalid candidate index");
        return candidates[_index];
    }

    function getVoter(uint _voterIndex) public view returns (Voter memory) {
        require(_voterIndex < totalCandidates, "Invalid voter index");
        return voters[_voterIndex];
    }

    function getTotalVotes(uint _candidateIndex) public view returns (uint) {
        require(_candidateIndex < totalCandidates, "Invalid candidate index");
        return candidates[_candidateIndex].voteCount;
    }

    function getWinner() public view returns (string memory) {
        uint maxVotes = 0;
        uint winnerIndex = 0;
        for (uint i = 0; i < totalCandidates; i++) {
            if (candidates[i].voteCount > maxVotes) {
                maxVotes = candidates[i].voteCount;
                winnerIndex = i;
            }
        }
        return candidates[winnerIndex].name;
    }
}
```

This smart contract allows the owner of the contract to add and remove candidates, authorize voters, and cast votes. It also includes functions to retrieve candidate and voter information, as well as to get the total votes and the winner of the election. The contract ensures that only authorized voters can vote and that each voter can only vote once. The contract also emits events for various actions, which can be used to track the contract's activity.

